const a=e=>{if(!e)return["Something unexpected happened. Please try again."];if(e.message&&e.message.toLowerCase().includes("network"))return["Unable to connect to the server. Please check your internet connection."];if(e.status===400&&e.validationErrors){const t=[];if(Object.values(e.validationErrors).forEach(n=>{Array.isArray(n)?n.forEach(s=>{t.push(s)}):typeof n=="string"&&t.push(n)}),t.length>0)return t}switch(e.status){case 400:return["Please check the information you entered."];case 401:return["Incorrect email or password."];case 403:return["You don't have permission to perform this action."];case 404:return["The requested resource was not found."];case 409:return["An account with this information already exists."];case 429:return["Too many requests. Please try again later."];case 500:return["Something went wrong. Please try again later."]}return["Something unexpected happened. Please try again."]};export{a as p};
